SELECT ccc.id, ccc.is_consented, ccc.customer_id, ccc.channel_id, ccc.created_at, ccc.updated_at, ccc.created_by, ccc.updated_by, ccc.is_deleted FROM customer_channel_consent ccc INNER JOIN channel c ON c.id = ccc.channel_id AND c.is_deleted = 0 WHERE ccc.is_deleted = 0
AND c.channel_type = #{channel}
ORDER BY ccc.channel_id, ccc.customer_id

